  ('cf5ca28a-341f-40f9-8f0d-9c685146a1f9', 'd2095080-447a-4d39-b9d4-82102c2b05af', 'Peito Pequeno', '3 pedaços de filé de sassami, crocantes por fora, macios por dentro e levemente picantes, com molho exclusivo da casa.', 31, false, 'https://static.ifood-static.com.br/image/upload/t_high/pratos/18015426-6666-4bf6-bf69-999ee181ad12/202609231523_9aveef4cmqa.png', '07af7753-b39e-4cc5-b7aa-a72a874ce2f8', false, true, 1),
  ('bc388204-7de7-47c0-afc4-ee7f46be52dd', 'd2095080-447a-4d39-b9d4-82102c2b05af', 'Peito Médio', '6 pedaços de filé de sassami, crocantes, macios e levemente picantes, com dois molhos da casa.', 54, false, 'https://static.ifood-static.com.br/image/upload/t_high/pratos/18015426-6666-4bf6-bf69-999ee181ad12/202609231523_c1ewdu1ziwo.png', '197f4191-dcae-4b8f-b103-82a173e77444', false, true, 2),
  ('567ffeae-15fd-4dac-92fb-a02ec867192a', 'd2095080-447a-4d39-b9d4-82102c2b05af', 'Peito Grande', '12 pedaços de filé de sassami, crocantes, macios e levemente picantes, com três molhos da casa.', 89, false, 'https://static.ifood-static.com.br/image/upload/t_high/pratos/18015426-6666-4bf6-bf69-999ee181ad12/202609231523_fhdeps7cht8.png', '470bfd3a-4823-4fa1-b28a-9c12da294383', true, true, 3),
