  ('e751eb94-69bf-4da4-97a9-2dd4b1fb4c14', 'd2095080-447a-4d39-b9d4-82102c2b05af', 'Croquinho Supremo', 'Cubinhos de sassami empanados e dourados, com dois molhos à sua escolha direto no pote.', 38, false, 'https://static.ifood-static.com.br/image/upload/t_high/pratos/18015426-6666-4bf6-bf69-999ee181ad12/202609231523_2qny17icyk8.png', '68f2aec1-b85d-4f3f-800d-a31dc49fe871', true, true, 5),
  ('d8afada8-b1f9-4569-a4e1-a46760f5ca91', '60c07dcc-d459-4943-8550-6a1787e5dd40', '2 Filés + Refri Lata', 'Dois filés de frango empanados e crocantes, com refrigerante lata.', 24, true, 'https://static.ifood-static.com.br/image/upload/t_high/pratos/3e600039-d014-42d9-9f38-9a2be59375c4/202609092051_moa7v9a9vj8.png', 'caff9328-6e5f-4939-8322-0dcbeb3bba3f', false, true, 1),
  ('71131c46-e624-4889-814b-42d29ee64450', '60c07dcc-d459-4943-8550-6a1787e5dd40', '2x1 Fnp Churras ou Fnp Meladinho', 'Pediu um Fnp Meladinho ou Fnp Churras, ganha outro.', 24, false, 'https://static.ifood-static.com.br/image/upload/t_high/pratos/18015426-6666-4bf6-bf69-999ee181ad12/202609231523_mp75s43u4e.png', '3d60e8e1-034c-49c4-8538-3255ed7b43c2', false, true, 2),
  ('41827347-5ceb-4a14-8d5a-3f27f685be46', '60c07dcc-d459-4943-8550-6a1787e5dd40', 'Levinho na Conta', 'Croquinho empanado com molho agridoce picante e barbecue, em dose dupla.', 90, true, 'https://static.ifood-static.com.br/image/upload/t_high/pratos/18015426-6666-4bf6-bf69-999ee181ad12/202609231523_yh05xmsdor.png', '67db9b18-8cbb-4aa9-82c0-0b80aee10273', false, true, 3),
