  ('8b6424ee-ae0d-4c3a-978a-1ef1937063b7', '48eab843-783b-4a15-a952-c5fba398ea54', 'Combo Fnp Caramelo', 'Pão fofinho, frango empanado crocante, anel de cebola, Molho Fnp e queijo coalho.', 39, true, 'https://static.ifood-static.com.br/image/upload/t_high/pratos/1ba08850-86df-4e92-b00d-c1b504a725fa/202606151025_klngvo6g1gr.png', '35c80113-5a43-470f-bbaf-351926b3dbd3', false, true, 1),
